'use strict';
const $=(s,p=document)=>p.querySelector(s),$$=(s,p=document)=>[...p.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data,view='atlas',topicTab='guide',search='',topicFilter='all',statusFilter='all',solutionsInExam=false,tick,toastTimeout;
let state={ratings:{},notes:{},bookmarks:{},rubrics:{},timer:{}};
let currentUser=null,profileReady=false,cloudAvailable=false,saveTimeout,lastSaved={},pendingSave=false;
const freshState=()=>({ratings:{},notes:{},bookmarks:{},rubrics:{},timer:{}});
const storageKey=()=>currentUser?'symbolic-atlas-user-'+currentUser.id:'symbolic-atlas-v1';
try{Object.assign(state,JSON.parse(localStorage.getItem('symbolic-atlas-v1')||'{}'));document.documentElement.dataset.theme=localStorage.getItem('symbolic-atlas-theme')||'light'}catch{}
function persist(){try{localStorage.setItem(storageKey(),JSON.stringify(state))}catch{$('#storage-note').textContent='Browser storage unavailable; export to keep progress.'}updateProgress();if(profileReady&&currentUser&&cloudAvailable){clearTimeout(saveTimeout);pendingSave=true;saveTimeout=setTimeout(saveCloud,850)}}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),2400)}
function updateProgress(){if(!data)return;const done=data.exercises.filter(q=>state.ratings[q.id]==='confident').length;$('#progress-number').textContent=`${done} / ${data.exercises.length}`;$('#progress-bar').style.width=`${100*done/data.exercises.length}%`}
function route(){clearInterval(tick);const hash=location.hash.slice(1)||'atlas';view=hash;$$('[data-nav]').forEach(a=>a.classList.toggle('active',hash===a.dataset.nav||(hash.startsWith('mock-')&&a.dataset.nav==='mocks')));$$('.topic-link').forEach(a=>a.classList.toggle('active',hash===a.hash.slice(1)));if(hash==='atlas')renderAtlas();else if(hash==='practice')renderPractice();else if(hash==='mocks')renderMocks();else if(hash==='sources')renderSources();else if(hash==='slides')renderSlides();else if(hash==='profile')renderProfile();else if(hash==='mastery')renderMastery();else if(hash==='challenge')renderChallenges();else if(hash.startsWith('topic-'))renderTopic(hash.slice(6));else if(hash.startsWith('mock-'))renderExam(hash);else{location.hash='atlas';return}updateProgress()}
function intro(k,title,desc){return `<div class="page-kicker">${k}</div><h1>${title}</h1><p class="lede">${desc}</p>`}
function mapSVG(){const nodes=[{x:148,y:90,w:195,h:94,id:'prop',name:'Propositional logic',sub:'Truth & consequence',icon:'⊨'},{x:423,y:77,w:197,h:99,id:'fol',name:'First-order logic',sub:'Quantifiers & witnesses',icon:'∀'},{x:694,y:110,w:199,h:100,id:'plan',name:'Planning',sub:'States & actions',icon:'⇢'},{x:713,y:270,w:213,h:98,id:'fca',name:'Concepts & rules',sub:'Closure & patterns',icon:'⋄'},{x:424,y:332,w:203,h:94,id:'fuzzy',name:'Fuzzy & soft logic',sub:'Degrees & constraints',icon:'≈'},{x:146,y:279,w:204,h:100,id:'proof',name:'Theorem proving',sub:'Terms & proofs',icon:'λ'},{x:408,y:203,w:201,h:94,id:'dl',name:'Description logic',sub:'Concepts & models',icon:'⊑'}];return `<svg class="atlas-svg" viewBox="0 0 860 410" role="img" aria-label="Map of seven course topics. Choose a topic using a map island or the sidebar."><defs><pattern id="ripples" width="32" height="28" patternUnits="userSpaceOnUse"><path d="M8 20q4-3 8 0t8 0" fill="none" stroke="#b4c1b0" stroke-width=".5" opacity=".3"/></pattern></defs><rect width="860" height="410" fill="url(#ripples)"/><path class="route" d="M150 90 Q290 20 423 77 T694 110 Q820 190 713 270 T424 332 Q260 370 146 279 Q-10 175 148 90 M423 77L408 203L713 270 M146 279L408 203L148 90 M408 203L424 332"/><text x="307" y="147" class="map-water">The Sea of Inference</text><text x="570" y="365" class="map-water" style="font-size:10px">from syntax to meaning</text><g transform="translate(62 355)" fill="none" stroke="#9aa086"><path d="M0-20V20M-20 0H20M-12-12L12 12M12-12L-12 12"/><path d="M0-17L4 0L0 12L-4 0Z" fill="#a0aa8d"/><text y="-26" text-anchor="middle" fill="#7e8872" stroke="none" font-size="8">N</text></g>${nodes.map(n=>{const t=data.topics.find(t=>t.id===n.id),x=n.x-n.w/2,y=n.y-n.h/2;return `<a href="#topic-${n.id}" class="island" aria-label="${esc(t.title)}"><title>${esc(t.title)} · open guide and exercises</title><g transform="translate(${x} ${y})"><path class="land" d="M14 24 Q0 6 36 9 Q65-5 95 7 Q127-2 ${n.w-16} 15 Q${n.w+5} 25 ${n.w-4} 45 Q${n.w+5} 64 ${n.w-21} ${n.h-10} Q${n.w-54} ${n.h+2} ${n.w-77} ${n.h-6} Q70 ${n.h+4} 44 ${n.h-10} Q4 ${n.h-4} 10 53 Q-3 41 14 24Z"/><path class="terrain-line" d="M22 36q14-14 29-9m-26 8q13-9 22-7M142 62q13-8 27-4"/><path class="terrain-hill" d="M24 62l7-12 7 12m-2 0 7-10 7 10"/><text class="map-icon" x="${n.w/2}" y="35" text-anchor="middle" style="fill:${t.color}">${n.icon}</text><text x="${n.w/2}" y="56" text-anchor="middle">${n.name}</text><text class="map-n" x="${n.w/2}" y="73" text-anchor="middle">${t.n} · ${n.sub}</text></g></a>`}).join('')}</svg>`}
function renderAtlas(){$('#main').innerHTML=`<div class="hero-top"><div>${intro('A field guide for the written exam','Make sense of<br><em>symbolic intelligence.</em>','Seven regions. One connected course. Read the slides, work through 112 written exercises, then test yourself on six practice papers.')}</div><div class="hero-stamp">A COURSE IN<strong>7</strong>CONNECTED IDEAS</div></div><div class="atlas-wrap"><div class="atlas-topline"><span>THE SYMBOLIC LANDSCAPE</span><span>AN ATLAS OF IDEAS · 2026 / 27</span></div>${mapSVG()}<div class="map-bottom"><span class="legend"><i></i> Connected ideas, not a required learning order</span><span>Select a region to begin exploring ↗</span></div></div><div class="section-top"><h2>Choose your next step</h2><span>Learn it. Write it. Explain it.</span></div><div class="action-grid"><a class="action-card" href="#practice"><small>01 / PRACTISE THE REASONING</small><span class="arrow">↗</span><h3>112 written exercises</h3><p>Translations, proofs, calculations and countermodels. Hints when you need them.</p></a><a class="action-card" href="#mocks"><small>02 / PUT IT TOGETHER</small><span class="arrow">↗</span><h3>Six practice papers</h3><p>All seven topics, optional timer, printable questions and a self-marking guide.</p></a><a class="action-card" href="#sources"><small>03 / LOOK BACK</small><span class="arrow">↗</span><h3>A verified past exam</h3><p>The official 2021 IA301 paper, with a clear guide to what overlaps today.</p></a></div><div class="atlas-study-links"><a class="btn challenge-entry" href="#challenge">Try the proof challenges ✦</a><a class="btn" href="#slides">The lecture library ↗</a><a class="btn" href="#mastery">Follow the mastery route ↗</a></div><div class="note-line">Based on your current Moodle materials. Exercises and mock papers are original practice, not predictions of the final exam.</div>`}
function renderTopic(id){const t=data.topics.find(t=>t.id===id);if(!t){location.hash='atlas';return}$('#main').innerHTML=intro(`Region ${t.n} / ${t.short}`,esc(t.title),esc(t.subtitle))+`<div class="tabs" role="tablist" aria-label="Topic sections">${[['guide','Field notes'],['visual','Interactive example'],['exercises','Written exercises'],['slides','Lecture slides']].map(([k,v])=>`<button role="tab" aria-selected="${topicTab===k}" class="${topicTab===k?'active':''}" data-tab="${k}">${v}</button>`).join('')}</div><div id="topic-content"></div>`;$$('[data-tab]').forEach(b=>b.onclick=()=>{topicTab=b.dataset.tab;renderTopic(id)});const body=$('#topic-content');if(topicTab==='guide'){body.innerHTML=`<div class="concept-grid">${t.concepts.map(c=>`<article class="concept"><h3>${esc(c.title)}</h3><p>${esc(c.body)}</p></article>`).join('')}</div><div class="callout"><strong>Where answers lose marks</strong><ul>${t.traps.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><h3>Can you do this without notes?</h3><div class="checklist">${t.checklist.map(x=>`<span>${esc(x)}</span>`).join('')}</div><div class="intro-actions button-row"><button class="btn primary" id="topic-practice">Work through 16 exercises ↗</button><button class="btn" data-open-slide="${t.slides[0].filename}">Read lecture slides ↗</button></div><p class="footer-note">Lecture files can be read here without leaving the atlas. Original Moodle source links remain in Sources.</p>`;$('#topic-practice').onclick=()=>{topicTab='exercises';renderTopic(id)}}else if(topicTab==='exercises'){body.innerHTML=`<p class="exercise-count">16 written exercises, including two challenges · write an attempt before opening a solution.</p>`+data.exercises.filter(q=>q.topic===id).map(q=>exerciseHTML(q)).join('');bindExercises(body)}else if(topicTab==='slides'){body.innerHTML=slidesFor(t)}else renderDemo(id,body)}
function exerciseHTML(q,marks=q.points,exam=false){const t=data.topics.find(t=>t.id===q.topic),rating=state.ratings[q.id]||'';return `<details class="exercise" data-exercise="${q.id}" ${exam?'open':''}><summary><span class="exercise-code" style="color:${t.color}">${q.id}</span><span class="exercise-title">${esc(q.title)}</span><span class="badge ${q.difficulty==='challenge'?'challenge-badge':''}">${esc(q.kind)}</span><span class="exercise-meta">${q.minutes} min · ${marks} pts</span></summary><div class="exercise-body"><div class="question-label">${esc(t.title)} / ${exam?'Original mock question':'Original written practice'}</div><p class="prompt">${esc(q.prompt)}</p><label class="scratch-label" for="note-${q.id}">Your reasoning · autosaved</label><textarea class="scratch" id="note-${q.id}" data-note="${q.id}" placeholder="Write the steps, or use paper and leave yourself a note…">${esc(state.notes[q.id]||'')}</textarea><div class="button-row">${!exam?`<button class="btn small" data-hint="${q.id}" aria-expanded="false">A small hint</button>`:''}<button class="btn small" data-solution="${q.id}" aria-expanded="${exam&&solutionsInExam}">${exam&&solutionsInExam?'Hide solution':'Reveal worked solution'}</button><button class="btn small" data-open-slide="${exerciseSlide(q,t)}">Refer to slides ↗</button><button class="btn small ${state.bookmarks[q.id]?'bookmarked':''}" data-bookmark="${q.id}" aria-pressed="${!!state.bookmarks[q.id]}" aria-label="Bookmark ${q.id}">${state.bookmarks[q.id]?'★ Saved':'☆ Save'}</button></div><div class="hint-box" id="hint-${q.id}" hidden>${esc(q.hint)}</div><section class="solution" id="solution-${q.id}" ${exam&&solutionsInExam?'':'hidden'}><h4>One complete route to the answer</h4><ol>${q.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="rubric"><strong>${exam?'Self-marking checklist · allocate '+marks+' points proportionally':'Self-check · suggested '+marks+' points, one per item'}</strong>${q.rubric.map((x,i)=>`<label><input type="checkbox" data-rubric="${q.id}-${i}" ${state.rubrics[q.id+'-'+i]?'checked':''}> ${esc(x)}</label>`).join('')}</div><p class="footer-note"><button class="text-button" data-open-slide="${exerciseSlide(q,t)}">${esc(t.title)} · slides${q.pages?' '+esc(q.pages):''} ↗</button> · Equivalent valid reasoning earns credit. These are suggested practice marks, not an official marking scheme.</p></section><div class="review-controls" aria-label="Self-assess ${q.id}">${[['again','Review again'],['learning','Getting there'],['confident','Confident']].map(([k,l])=>`<button data-rate="${q.id}" data-rating="${k}" aria-pressed="${rating===k}" class="rating ${rating===k?'selected':''}">${l}</button>`).join('')}</div></div></details>`}
function bindExercises(parent){$$('[data-note]',parent).forEach(x=>x.oninput=()=>{state.notes[x.dataset.note]=x.value;persist()});$$('[data-hint]',parent).forEach(b=>b.onclick=()=>{const box=$('#hint-'+b.dataset.hint);box.hidden=!box.hidden;b.setAttribute('aria-expanded',String(!box.hidden))});$$('[data-solution]',parent).forEach(b=>b.onclick=()=>{const box=$('#solution-'+b.dataset.solution);box.hidden=!box.hidden;b.textContent=box.hidden?'Reveal worked solution':'Hide solution';b.setAttribute('aria-expanded',String(!box.hidden))});$$('[data-bookmark]',parent).forEach(b=>b.onclick=()=>{const id=b.dataset.bookmark;state.bookmarks[id]=!state.bookmarks[id];b.textContent=state.bookmarks[id]?'★ Saved':'☆ Save';b.classList.toggle('bookmarked',state.bookmarks[id]);b.setAttribute('aria-pressed',String(state.bookmarks[id]));persist()});$$('[data-rate]',parent).forEach(b=>b.onclick=()=>{state.ratings[b.dataset.rate]=b.dataset.rating;$$(`[data-rate="${b.dataset.rate}"]`,parent).forEach(x=>{const selected=x.dataset.rating===b.dataset.rating;x.classList.toggle('selected',selected);x.setAttribute('aria-pressed',String(selected))});persist();toast(b.dataset.rating==='confident'?'Marked confident. Progress updated.':'Review status saved.')});$$('[data-rubric]',parent).forEach(x=>x.onchange=()=>{state.rubrics[x.dataset.rubric]=x.checked;persist()})}
function renderPractice(){$('#main').innerHTML=intro('The exercise notebook','Think it through.<br><em>Then write it down.</em>','112 original exercises across the current course. Start with a blank page, use a hint if you get stuck, and compare your reasoning with the worked answer. Challenge problems are marked separately.')+`<div class="filter-row"><input class="search-input" id="search" aria-label="Search exercises" placeholder="Search ideas, questions, or exercise IDs…" value="${esc(search)}"><select id="topic-filter" aria-label="Filter topic"><option value="all">All seven topics</option>${data.topics.map(t=>`<option value="${t.id}" ${topicFilter===t.id?'selected':''}>${t.n} · ${esc(t.title)}</option>`).join('')}</select><select id="status-filter" aria-label="Filter review status">${[['all','Any progress'],['again','Needs review'],['saved','Saved exercises'],['confident','Confident']].map(([k,l])=>`<option value="${k}" ${statusFilter===k?'selected':''}>${l}</option>`).join('')}</select><button id="random" class="btn">Pick one ↝</button></div><div class="exercise-count" id="count"></div><div id="exercise-list"></div>`;$('#search').oninput=e=>{search=e.target.value;filterList()};$('#topic-filter').onchange=e=>{topicFilter=e.target.value;filterList()};$('#status-filter').onchange=e=>{statusFilter=e.target.value;filterList()};$('#random').onclick=()=>{const candidates=filtered();if(!candidates.length){toast('No exercises match these filters.');return}const q=candidates[Math.floor(Math.random()*candidates.length)];const el=$(`[data-exercise="${q.id}"]`);el.open=true;el.scrollIntoView({behavior:'smooth',block:'start'})};filterList()}
function filtered(){const text=search.toLowerCase().trim();return data.exercises.filter(q=>(topicFilter==='all'||q.topic===topicFilter)&&(!text||[q.id,q.title,q.prompt,q.kind,...q.steps].join(' ').toLowerCase().includes(text))&&(statusFilter==='all'||(statusFilter==='saved'?state.bookmarks[q.id]:statusFilter==='again'?state.ratings[q.id]!=='confident':state.ratings[q.id]==='confident')))}
function filterList(){const list=filtered();$('#count').textContent=`${list.length} exercises · solutions hidden until you choose to reveal them`;$('#exercise-list').innerHTML=list.length?list.map(q=>exerciseHTML(q)).join(''):'<div class="empty">No exercises match. Try another topic or a shorter search.</div>';bindExercises($('#exercise-list'))}
function renderMocks(){$('#main').innerHTML=intro('The practice examination room','Bring the ideas<br><em>onto one page.</em>','Six original 20-point papers, each covering all seven regions. Use paper for your answers. The four regular papers use a 120-minute practice timer; the two challenge papers use 210 minutes. These are practice settings, not confirmed exam durations.')+data.mocks.map((m,i)=>`<article class="mock-card"><div class="eyebrow">${m.difficulty==='challenge'?'CHALLENGE':'PRACTICE'} PAPER ${i+1} · 7 QUESTIONS · 20 POINTS · ${m.minutes} MIN</div><h2>${esc(m.title)}</h2><p>${m.questions.map(x=>data.topics.find(t=>t.id===data.exercises.find(q=>q.id===x.id).topic).title).join(' · ')}</p><div class="button-row"><a class="btn primary" href="#${m.id}">Open paper ↗</a><span class="badge">Original practice, not a past exam</span></div></article>`).join('')+'<div class="note-line">The real historical paper lives in Past exams. Its older syllabus includes subjects outside today’s seven-section course.</div>'}
function renderExam(id){const m=data.mocks.find(x=>x.id===id);if(!m){location.hash='mocks';return}solutionsInExam=false;$('#main').innerHTML=intro('Original practice / 20 points',esc(m.title),'Answer all seven questions. Show formulas, intermediate calculations and justification. The suggested points are for self-assessment, not an official grade.')+`<div class="mock-toolbar"><div><div class="eyebrow">OPTIONAL PRACTICE TIMER</div><span class="timer" id="timer">120:00</span></div><div class="button-row"><button class="btn" id="timer-start">Start / resume</button><button class="btn" id="timer-pause">Pause</button><button class="btn" id="timer-reset">Reset</button><button class="btn" id="print-paper">Print questions</button><button class="btn primary" id="all-solutions">Show answer guide</button></div></div><div id="exam-questions">${m.questions.map(x=>exerciseHTML(data.exercises.find(q=>q.id===x.id),x.marks,true)).join('')}</div><p class="footer-note">Timed mode records time only; written answers require your own marking. No automatic correctness grade is inferred from keywords.</p>`;bindExercises($('#exam-questions'));let timer=state.timer[id]||{remaining:m.minutes*60,running:false};if(timer.running&&timer.until){timer.remaining=Math.max(0,Math.ceil((timer.until-Date.now())/1000));timer.running=false}function show(){const s=Math.max(0,timer.remaining);$('#timer').textContent=`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`;state.timer[id]=timer;persist()}function pause(){if(timer.running)timer.remaining=Math.max(0,Math.ceil((timer.until-Date.now())/1000));timer.running=false;clearInterval(tick);show()}$('#timer-start').onclick=()=>{if(timer.running)return;if(timer.remaining<=0){toast('Reset the timer to start another attempt.');return}timer.running=true;timer.until=Date.now()+timer.remaining*1000;tick=setInterval(()=>{timer.remaining=Math.max(0,Math.ceil((timer.until-Date.now())/1000));show();if(timer.remaining===0){pause();toast('Practice time is up. Finish your current thought, then mark your work.')}},1000);show()};$('#timer-pause').onclick=pause;$('#timer-reset').onclick=()=>{pause();timer.remaining=m.minutes*60;show()};$('#print-paper').onclick=()=>{const boxes=$$('.solution');const hidden=boxes.map(x=>x.hidden);boxes.forEach(x=>x.hidden=true);window.print();boxes.forEach((x,i)=>x.hidden=hidden[i])};$('#all-solutions').onclick=()=>{solutionsInExam=!solutionsInExam;$$('.solution').forEach(x=>x.hidden=!solutionsInExam);$$('[data-solution]').forEach(x=>{x.textContent=solutionsInExam?'Hide solution':'Reveal worked solution';x.setAttribute('aria-expanded',String(solutionsInExam))});$('#all-solutions').textContent=solutionsInExam?'Hide answer guide':'Show answer guide'};show()}
function renderSources(){$('#main').innerHTML=intro('Sources / scope / provenance','A past paper.<br><em>A current perspective.</em>','A verified historical exam is useful evidence of question style. It is not a promise about this year’s scope, rules or marking.')+data.sources.map(s=>`<article class="source-card"><div class="source-badge">${esc(s.type)}</div><h3>${esc(s.label)}</h3><p>${esc(s.note)}</p><a class="source-link" href="${s.url}" target="_blank" rel="noopener">Open original source ↗</a></article>`).join('')+`<div class="callout">${esc(data.coverage_note)}</div><h2>Your current coverage map</h2><table class="data-table coverage-table"><thead><tr><th>Current region</th><th>Written skills to review</th><th>Source</th></tr></thead><tbody>${data.topics.map(t=>`<tr><td><a href="#topic-${t.id}">${t.n} · ${esc(t.title)}</a></td><td>${t.checklist.map(esc).join(' · ')}</td><td><a href="${t.source}" target="_blank" rel="noopener" class="source-link">Lecture ↗</a></td></tr>`).join('')}</tbody></table><div class="connection"><strong>How to use the 2021 paper</strong><p>Use its proof, formalization, derivation and hand-calculation style. Review all seven current topics here, including planning, fuzzy/soft logic, theorem proving and description logic. Treat the older modal-logic and revision sections as historical scope unless your teacher includes them.</p></div><p class="footer-note">Research checked 24 October 2026: current Moodle resources, public course catalogues, lecturer course page and public searches for CSC_5AI01_TP / IA301 exams. No newer verified paper was located. All 112 exercises and six mock papers on this site are newly authored study material.</p>`}
function renderDemo(id,body){if(id==='prop')demoTruth(body);if(id==='fol')demoQuantifiers(body);if(id==='plan')demoPlan(body);if(id==='fca')demoFCA(body);if(id==='fuzzy')demoFuzzy(body);if(id==='proof')demoLambda(body);if(id==='dl')demoDL(body)}
function demoTruth(body){body.innerHTML=`<section class="demo"><h3>A truth table is a map of possible worlds</h3><p>Select a claim and find the rows where the premises hold. One countermodel defeats entailment.</p><select id="truth-choice" aria-label="Choose logical claim"><option value="chain">p→q, q→r ⊨ p→r</option><option value="converse">p→q, q ⊨ p ?</option><option value="unsat">p∨q, p→r, q→r, ¬r</option></select><div id="truth-result"></div></section>`;function render(){const mode=$('#truth-choice').value;let count=0,counter=0;const rows=[];for(let n=0;n<8;n++){const p=!!(n&4),q=!!(n&2),r=!!(n&1);const premise=mode==='chain'?(!p||q)&&(!q||r):mode==='converse'?(!p||q)&&q:(p||q)&&(!p||r)&&(!q||r)&&!r;const conclusion=mode==='chain'?(!p||r):mode==='converse'?p:false;if(premise)count++;if(premise&&!conclusion)counter++;rows.push(`<tr class="${premise?'highlight-row':''}"><td>${+p}</td><td>${+q}</td><td>${+r}</td><td>${premise?'true':'false'}</td><td>${mode==='unsat'?'—':conclusion?'true':'false'}</td><td>${premise&&!conclusion&&mode!=='unsat'?'countermodel':''}</td></tr>`)}$('#truth-result').innerHTML=`<table><thead><tr><th>p</th><th>q</th><th>r</th><th>All premises</th><th>Conclusion</th><th></th></tr></thead><tbody>${rows.join('')}</tbody></table><div class="result-box">${count} model${count===1?'':'s'} of the premises. ${mode==='unsat'?'No model: the knowledge base is unsatisfiable.':counter?`${counter} countermodel(s): the entailment fails.`:'No countermodels: the entailment holds.'}</div>`}$('#truth-choice').onchange=render;render()}
function demoQuantifiers(body){body.innerHTML=`<section class="demo"><h3>Local witnesses or one shared witness?</h3><p>Toggle the relation R on a two-object domain. Rows choose x, columns choose y. Then compare the two quantifier orders.</p><div id="relation"></div><div id="quant-result" class="result-box"></div></section>`;const rel=[[true,false],[false,true]];function render(){$('#relation').innerHTML=`<table><thead><tr><th>R(x,y)</th><th>y=a</th><th>y=b</th></tr></thead><tbody>${rel.map((row,i)=>`<tr><th>x=${i?'b':'a'}</th>${row.map((v,j)=>`<td><button class="btn small" data-cell="${i},${j}" aria-label="Toggle R(${'ab'[i]},${'ab'[j]})" aria-pressed="${v}">${v?'✓ true':'− false'}</button></td>`).join('')}</tr>`).join('')}</tbody></table>`;$('#quant-result').innerHTML=`∀x∃y R(x,y): <strong>${rel.every(row=>row.some(Boolean))}</strong> · every row has a witness.<br>∃y∀x R(x,y): <strong>${[0,1].some(j=>rel.every(row=>row[j]))}</strong> · one column works for every row.`;$$('[data-cell]').forEach(b=>b.onclick=()=>{const[i,j]=b.dataset.cell.split(',').map(Number);rel[i][j]=!rel[i][j];render()})}render()}
function demoPlan(body){let stage=0;const states=[['At(A)','DoorClosed'],['At(A)','DoorOpen'],['At(B)','DoorOpen'],['At(B)','DoorClosed']];body.innerHTML=`<section class="demo"><h3>A plan is a sequence of legal state changes</h3><p>Goal: At(B) ∧ DoorClosed. Only applicable actions can advance the state.</p><div class="step-track" id="plan-track"></div><div class="result-box" id="plan-state"></div><div class="button-row" style="margin-top:16px"><button class="btn" data-action="Open">Open</button><button class="btn" data-action="Go">Go</button><button class="btn" data-action="Close">Close</button><button class="btn" id="plan-reset">Reset</button></div><p id="plan-feedback" aria-live="polite"></p></section>`;function render(){$('#plan-track').innerHTML=states.map((_,i)=>`<span class="step-dot ${i===stage?'current':''}">S${i}</span>`).join('');$('#plan-state').textContent=`S${stage} = {${states[stage].join(', ')}}${stage===3?' · Goal reached ✓':''}`};$$('[data-action]').forEach(b=>b.onclick=()=>{const required=['Open','Go','Close'][stage];if(b.dataset.action!==required){$('#plan-feedback').textContent=`${b.dataset.action} is inapplicable in this state. Check its preconditions.`;return}stage++;$('#plan-feedback').textContent=stage===3?'All goal facts now hold. Three actions were necessary.':'Action applied. Unaffected facts persist.';render()});$('#plan-reset').onclick=()=>{stage=0;$('#plan-feedback').textContent='';render()};render()}
function demoFCA(body){body.innerHTML=`<section class="demo"><h3>From attributes to objects, then back again</h3><p>Context: 1={a,b}, 2={a,c}, 3={a,b,c}. Select an attribute set B to watch its closure B″.</p><div class="button-row">${['a','b','c'].map(a=>`<label class="btn"><input type="checkbox" data-attribute="${a}"> ${a}</label>`).join('')}</div><div class="demo-grid"><div id="closure-result" class="result-box"></div><svg class="diagram" viewBox="0 0 260 235" aria-label="Four concepts in a diamond Hasse diagram"><g fill="none" stroke="#a5b192"><path d="M130 30L50 115L130 200L210 115Z"/></g>${[[130,30,'{a}'],[50,115,'{a,b}'],[210,115,'{a,c}'],[130,200,'{a,b,c}']].map(([x,y,label])=>`<g data-intent="${label.slice(1,-1)}"><circle cx="${x}" cy="${y}" r="16" fill="#dfe7d1" stroke="#879b74"/><text x="${x}" y="${y+32}" text-anchor="middle" fill="currentColor" font-size="12">${label}</text></g>`).join('')}</svg></div><p>Concepts are ordered by extent inclusion: the top intent is {a}, the bottom intent is {a,b,c}.</p></section>`;const context=[['a','b'],['a','c'],['a','b','c']];function render(){const B=$$('[data-attribute]:checked').map(x=>x.dataset.attribute),extent=context.map((row,i)=>({row,i})).filter(x=>B.every(a=>x.row.includes(a))),closure=['a','b','c'].filter(a=>extent.every(x=>x.row.includes(a)));$('#closure-result').innerHTML=`B = {${B.join(',')}}<br>B′ = {${extent.map(x=>x.i+1).join(',')}}<br>B″ = {${closure.join(',')}}<br>${B.join(',')===closure.join(',')?'B is closed.':'Closure adds '+closure.filter(a=>!B.includes(a)).join(',')+'.'}`;$$('[data-intent] circle').forEach(c=>c.setAttribute('fill',c.parentElement.dataset.intent===closure.join(',')?'#7f9b64':'#dfe7d1'))}$$('[data-attribute]').forEach(x=>x.onchange=render);render()}
function demoFuzzy(body){body.innerHTML=`<section class="demo"><h3>One pair of degrees, different operators</h3><p>Move the sliders. The formulas stay visible so you can reproduce the calculation on paper.</p><div class="range-row"><label for="fuzzy-a">a</label><input type="range" id="fuzzy-a" min="0" max="100" value="70"><output id="out-a">0.70</output></div><div class="range-row"><label for="fuzzy-b">b</label><input type="range" id="fuzzy-b" min="0" max="100" value="40"><output id="out-b">0.40</output></div><div id="fuzzy-table"></div></section>`;function render(){const a=$('#fuzzy-a').value/100,b=$('#fuzzy-b').value/100;$('#out-a').textContent=a.toFixed(2);$('#out-b').textContent=b.toFixed(2);const rows=[['Minimum','min(a,b)',Math.min(a,b),'max(a,b)',Math.max(a,b)],['Product','a×b',a*b,'a+b−ab',a+b-a*b],['Łukasiewicz','max(0,a+b−1)',Math.max(0,a+b-1),'min(1,a+b)',Math.min(1,a+b)]];$('#fuzzy-table').innerHTML=`<table><thead><tr><th>Operators</th><th>Conjunction</th><th>Value</th><th>Dual disjunction</th><th>Value</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r[0]}</td><td>${r[1]}</td><td>${r[2].toFixed(2)}</td><td>${r[3]}</td><td>${r[4].toFixed(2)}</td></tr>`).join('')}</tbody></table>`}$('#fuzzy-a').oninput=render;$('#fuzzy-b').oninput=render;render()}
function demoLambda(body){let step=0;const steps=[['(λx.λy.x) y','The argument y is free. Direct substitution must not capture it.'],['(λx.λz.x) y','Alpha-rename the inner bound variable y to fresh z.'],['λz.y','Beta-reduce: substitute y for the free occurrence of x. The y remains free.']];body.innerHTML=`<section class="demo"><h3>A reduction, one justified step at a time</h3><p>Avoid the common mistake of turning a free variable into a bound one.</p><div id="lambda-formula" class="formula"></div><p id="lambda-caption" aria-live="polite"></p><div class="button-row"><button class="btn" id="lambda-prev">← Previous</button><button class="btn primary" id="lambda-next">Next step →</button><button class="btn" id="lambda-reset">Reset</button></div></section>`;function render(){$('#lambda-formula').textContent=steps[step][0];$('#lambda-caption').textContent=steps[step][1];$('#lambda-prev').disabled=step===0;$('#lambda-next').disabled=step===steps.length-1}$('#lambda-prev').onclick=()=>{step--;render()};$('#lambda-next').onclick=()=>{step++;render()};$('#lambda-reset').onclick=()=>{step=0;render()};render()}
function demoDL(body){let edges=[false,false],member=[true,false];body.innerHTML=`<section class="demo"><h3>“All” does not mean “some”</h3><p>Toggle r-edges from a and whether b,c belong to concept C. The two restrictions are evaluated at a.</p><div class="demo-grid"><div><div class="button-row"><button class="btn" data-edge="0">a → b</button><button class="btn" data-edge="1">a → c</button></div><div class="button-row" style="margin-top:12px"><label><input type="checkbox" id="member-b" checked> b ∈ C</label><label><input type="checkbox" id="member-c"> c ∈ C</label></div><div id="dl-result" class="result-box" style="margin-top:18px"></div></div><svg class="diagram" viewBox="0 0 280 220" aria-label="Domain objects a,b,c with toggled r-edges"><defs><marker id="arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="#7b9568"/></marker></defs><g fill="none" stroke="#7b9568" stroke-width="2" marker-end="url(#arrow)"><path id="edge-b" d="M70 100L185 55"/><path id="edge-c" d="M70 120L185 165"/></g><circle cx="50" cy="110" r="25" fill="#dfe5d6"/><circle id="circle-b" cx="215" cy="45" r="25"/><circle id="circle-c" cx="215" cy="175" r="25"/><g font-size="15" fill="#344a38" text-anchor="middle"><text x="50" y="115">a</text><text x="215" y="50">b</text><text x="215" y="180">c</text></g></svg></div></section>`;function render(){$('#edge-b').style.opacity=edges[0]?1:.1;$('#edge-c').style.opacity=edges[1]?1:.1;$('#circle-b').setAttribute('fill',member[0]?'#b3c99d':'#e4dfd0');$('#circle-c').setAttribute('fill',member[1]?'#b3c99d':'#e4dfd0');$$('[data-edge]').forEach((b,i)=>{b.setAttribute('aria-pressed',String(edges[i]));b.style.background=edges[i]?'var(--soft)':''});$('#dl-result').innerHTML=`a ∈ ∀r.C: <strong>${edges.every((e,i)=>!e||member[i])}</strong><br>a ∈ ∃r.C: <strong>${edges.some((e,i)=>e&&member[i])}</strong><br>${edges.every(e=>!e)?'No successors: the universal holds vacuously.':'Every existing edge is checked; no missing edges are assumed.'}`};$$('[data-edge]').forEach((b,i)=>b.onclick=()=>{edges[i]=!edges[i];render()});$('#member-b').onchange=e=>{member[0]=e.target.checked;render()};$('#member-c').onchange=e=>{member[1]=e.target.checked;render()};render()}
$('#theme').onclick=()=>{const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('symbolic-atlas-theme',theme)}catch{}$('#theme').setAttribute('aria-label','Switch to '+(theme==='dark'?'light':'dark')+' theme')};$('#search-open').onclick=()=>{if(location.hash==='#practice')$('#search').focus();else{location.hash='practice';setTimeout(()=>$('#search')?.focus(),80)}};$('#export').onclick=()=>{const blob=new Blob([JSON.stringify({exported:new Date().toISOString(),...state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='symbolic-ai-review-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progress and notes exported.')};
fetch('content.json').then(r=>{if(!r.ok)throw new Error('Content could not load');return r.json()}).then(async d=>{data=d;await initProfile();$('#topic-nav').innerHTML=data.topics.map(t=>`<a class="topic-link" href="#topic-${t.id}"><span class="num">${t.n}</span><span>${esc(t.title)}</span><span class="dot" style="background:${t.color}"></span></a>`).join('');window.addEventListener('hashchange',()=>{topicTab='guide';route();window.scrollTo(0,0)});route()}).catch(e=>{$('#main').innerHTML='<h1>The atlas could not load.</h1><p>Please reload the page. Your browser notes have not been cleared.</p>';console.error(e)});
function slidesFor(t){return `<div class="slide-cards">${t.slides.map(s=>`<article class="slide-card"><span class="slide-symbol">${({prop:'⊨',fol:'∀',plan:'⇢',fca:'⋄',fuzzy:'≈',proof:'λ',dl:'⊑'})[t.id]}</span><div><div class="eyebrow">LECTURE ${t.n} · ${s.format.toUpperCase()} ${s.pages?'· '+s.pages+' PAGES':''}</div><h3>${esc(s.title)}</h3><div class="button-row"><button class="btn primary" data-open-slide="${s.filename}">Read in atlas</button><a class="source-link" href="${s.url}" target="_blank" rel="noopener">Open / download ↗</a></div></div></article>`).join('')}</div>`}
function renderSlides(){$('#main').innerHTML=intro('The lecture library','Keep the source<br><em>within reach.</em>','Eight lecture decks and three supporting handouts from your current course. Open a reader without leaving your exercise, or download a copy for revision.')+data.topics.map(t=>`<section class="library-topic"><h2>${t.n} / ${esc(t.title)}</h2>${slidesFor(t)}</section>`).join('')+`<h2>Supporting handouts</h2><div class="slide-cards">${(data.handouts||[]).map(h=>`<article class="concept"><h3>${esc(h.title)}</h3><button class="btn small" data-open-slide="${h.filename}">Open handout ↗</button></article>`).join('')}</div>`+'<p class="footer-note">Original lecturer files are preserved. The current Description Logic Moodle file carries a 2025–2026 filename. Fuzzy Logic and PSL are HTML slide decks with embedded assets.</p>'}
function openSlide(filename){const slide=[...data.slides,...(data.handouts||[])].find(x=>x.filename===filename);if(!slide)return;$('#slide-reader-title').textContent=slide.title;$('#slide-download').href=slide.url;if(slide.format==='html')$('#slide-frame').setAttribute('sandbox','allow-scripts allow-popups allow-downloads');else $('#slide-frame').removeAttribute('sandbox');$('#slide-frame').src=slide.url;$('#slide-reader').showModal()}
document.addEventListener('click',e=>{const b=e.target.closest('[data-open-slide]');if(b)openSlide(b.dataset.openSlide)});
$('#slide-close').onclick=()=>{$('#slide-reader').close();$('#slide-frame').src='about:blank'};
$('#slide-reader').addEventListener('close',()=>{$('#slide-frame').src='about:blank'});
function localProfiles(){try{return JSON.parse(localStorage.getItem('symbolic-atlas-local-profiles')||'[]')}catch{return []}}
function writeProfiles(profiles){localStorage.setItem('symbolic-atlas-local-profiles',JSON.stringify(profiles))}
async function initLocalProfile(){
 const profiles=localProfiles();let id;try{id=localStorage.getItem('symbolic-atlas-active-local-profile')}catch{}
 currentUser=profiles.find(p=>p.id===id)||null;
 state=freshState();try{Object.assign(state,JSON.parse(localStorage.getItem(storageKey())||'{}'))}catch{}
 cloudAvailable=false;profileReady=true;
 $('#profile-link').textContent=currentUser?currentUser.name:'Profiles';
 $('#storage-note').textContent=currentUser?'Profile: '+currentUser.name+' · saved on this device.':'Guest profile · saved on this device.';
}
async function saveLocalCloud(){}
function switchLocalProfile(id){
 persist();if(id)localStorage.setItem('symbolic-atlas-active-local-profile',id);else localStorage.removeItem('symbolic-atlas-active-local-profile');location.reload();
}
function renderLocalProfile(){
 const profiles=localProfiles();
 $('#main').innerHTML=intro('Your study notebook','A place for<br><em>your own reasoning.</em>','Choose a separate profile for your notes, bookmarks and confidence ratings. Profiles live in this browser; no account sign-in is required.')+
 `<section class="profile-card"><div class="profile-avatar">${esc(currentUser?currentUser.name[0].toUpperCase():'⊢')}</div><h2>${esc(currentUser?currentUser.name:'Guest notebook')}</h2><label class="scratch-label" for="local-profile">Choose a notebook</label><select id="local-profile"><option value="">Guest</option>${profiles.map(p=>`<option value="${p.id}" ${currentUser?.id===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><div class="filter-row"><input id="new-profile-name" class="search-input" maxlength="50" placeholder="New profile name" aria-label="New profile name"><button id="new-profile-create" class="btn primary">Create profile</button></div><p>These are separate local notebooks, not password-protected accounts. Anyone using this browser can switch between them. For another device, export a copy and import it there.</p><div class="button-row"><button id="profile-export" class="btn">Export this notebook</button><label class="btn" for="profile-import">Import a notebook</label><input type="file" id="profile-import" accept="application/json,.json" hidden>${currentUser?'<button id="guest-import" class="btn">Copy missing entries from Guest</button>':''}</div></section><div class="concept-grid"><article class="concept"><h3>Everyone can start revising</h3><p>The atlas, slides, exercises and mock papers are public. Each visitor keeps their own browser notes and review progress.</p></article><article class="concept"><h3>Account sync</h3><p>This GitHub Pages edition works without a backend. It does not provide authenticated accounts or automatic sync across devices. Export and import let you move your own work.</p></article></div>`;
 $('#local-profile').onchange=e=>switchLocalProfile(e.target.value);
 $('#new-profile-create').onclick=()=>{const name=$('#new-profile-name').value.trim();if(!name){toast('Enter a profile name.');return}if(profiles.some(p=>p.name.toLowerCase()===name.toLowerCase())){toast('That profile already exists. Select it above.');return}const id=crypto.randomUUID();writeProfiles([...profiles,{id,name}]);switchLocalProfile(id)};
 $('#profile-export').onclick=()=>$('#export').click();
 $('#profile-import').onchange=async e=>{const file=e.target.files[0];if(!file)return;if(file.size>3000000){toast('That file is too large.');return}try{const imported=JSON.parse(await file.text());const validIds=new Set(data.exercises.map(q=>q.id));for(const g of ['ratings','notes','bookmarks','rubrics']){if(!imported[g]||typeof imported[g]!=='object'||Array.isArray(imported[g]))continue;for(const[k,v]of Object.entries(imported[g])){const exercise=g==='rubrics'?k.split('-')[0]:k;if(!validIds.has(exercise))continue;if(g==='notes'&&(typeof v!=='string'||v.length>30000))continue;if(g==='ratings'&&!['again','learning','confident'].includes(v))continue;if((g==='bookmarks'||g==='rubrics')&&typeof v!=='boolean')continue;if(!(k in state[g]))state[g][k]=v;}}persist();toast('Imported missing entries. Existing notes were kept.');}catch{toast('Could not read that notebook file.');}};
 if(currentUser)$('#guest-import').onclick=()=>{try{const guest=JSON.parse(localStorage.getItem('symbolic-atlas-v1')||'{}');for(const g of ['ratings','notes','bookmarks','rubrics'])for(const[k,v]of Object.entries(guest[g]||{}))if(!(k in state[g]))state[g][k]=v;persist();toast('Copied missing Guest entries.');}catch{toast('Could not read Guest notes.')}};
}
function renderMastery(){
 $('#main').innerHTML=intro('The mastery route','Explore. Explain.<br><em>Then start from blank paper.</em>','A course-bound checklist: first review the field notes and lecture pages, then solve the linked exercises independently. Revisit any step you cannot justify.')+`<div class="callout">${esc(data.masteryNote)}</div>`+data.topics.map(t=>{const exercises=data.exercises.filter(q=>q.topic===t.id),done=exercises.filter(q=>state.ratings[q.id]==='confident').length;return `<article class="mastery-region"><div class="section-top"><h2>${t.n} · ${esc(t.title)}</h2><span>${done} / ${exercises.length} confident</span></div><div class="coverage-skills">${(t.coverage||[]).map(c=>`<div><strong>${esc(c.skill)}</strong><span>${c.exerciseIds.map(esc).join(' · ')}</span></div>`).join('')}</div><p class="footer-note">${exercises.map(q=>`<a href="#topic-${t.id}" class="exercise-chip" data-jump-question="${q.id}" data-jump-topic="${t.id}">${q.id} ${state.ratings[q.id]==='confident'?'✓':''}</a>`).join('')}</p><div class="button-row"><a class="btn small" href="#topic-${t.id}">Review this region</a><button class="btn small" data-open-slide="${t.slides[0].filename}">Read slides</button></div></article>`}).join('')+'<section class="mock-card"><h2>The final check</h2><p>Try a fresh practice paper without hints, show your intermediate steps, and self-mark against the full reasoning. Explain each corrected mistake before marking it confident.</p><a href="#mocks" class="btn primary">Open six practice papers ↗</a></section>';
 $$('[data-jump-question]').forEach(a=>a.onclick=()=>{setTimeout(()=>{topicTab='exercises';renderTopic(a.dataset.jumpTopic);const el=$(`[data-exercise="${a.dataset.jumpQuestion}"]`);if(el){el.open=true;el.scrollIntoView({block:'start'})}},80)})
}
